import{_ as e,o as a,c as r,a4 as o}from"./chunks/framework.B0hSrcZ6.js";const l="/info/08-skills-routines.webp",n="/info/08-skills-routines-s1.webp",s="/info/08-skills-routines-s2.webp",i="/info/08-skills-routines-s3.webp",f=JSON.parse('{"title":"第 8 章 技能与例程：把一次成功变成每天自动跑","description":"本章讲解如何把操作沉淀为技能、将 Skill 写成 SOP，并组装为 Grok Bot 的 Routine 自动化触发。通过外部触发器与两段式检测，帮助校准时区并限制触发范围，防止任务空转浪费整周额度。","frontmatter":{},"headers":[],"relativePath":"part1/08-skills-routines.md","filePath":"part1/08-skills-routines.md","lastUpdated":1792415157000}'),h={name:"part1/08-skills-routines.md"};function d(p,t,g,c,k,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="第-8-章-技能与例程-把一次成功变成每天自动跑" tabindex="-1">第 8 章 技能与例程：把一次成功变成每天自动跑 <a class="header-anchor" href="#第-8-章-技能与例程-把一次成功变成每天自动跑" aria-label="Permalink to &quot;第 8 章 技能与例程：把一次成功变成每天自动跑&quot;">​</a></h1><p>别直接设定时。<strong>脱离人工盯梢易卡死，还会半夜三点误跑，空转耗尽整周额度。</strong></p><p>把操作沉淀为技能（Skill），组装成例程（Routine）：</p><ol><li>校准时区，规范 Webhook。</li><li>限制 Slack 触发范围。</li><li>加上虚拟机两段式检测。</li></ol><p><strong>设好边界，合上电脑后台也能稳定交付。</strong></p><p><img src="'+l+'" alt="技能与例程：把一次成功变成每天自动跑" width="1600" height="1013" decoding="async"></p><h2 id="技能的沉淀与引用-固定你的标准作业程序" tabindex="-1">技能的沉淀与引用：固定你的标准作业程序 <a class="header-anchor" href="#技能的沉淀与引用-固定你的标准作业程序" aria-label="Permalink to &quot;技能的沉淀与引用：固定你的标准作业程序&quot;">​</a></h2><p><img src="'+n+`" alt="技能的沉淀与引用：固定你的标准作业程序" width="1600" height="1013" loading="lazy" decoding="async"></p><p>技能是保存在账号里的操作指令，<strong>名下所有 Bot 都能直接调用</strong>。</p><h3 id="怎么沉淀技能" tabindex="-1">怎么沉淀技能 <a class="header-anchor" href="#怎么沉淀技能" aria-label="Permalink to &quot;怎么沉淀技能&quot;">​</a></h3><p><strong>方式一：对话后文本总结</strong> 任务跑通后先别关会话，直接让当前 Bot 提炼保存。提示词要明确输入源、异常处理与越界限制，直接发送这段模板。</p><details class="details custom-block"><summary>怎么沉淀技能</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请把我们刚刚完成的这套流程保存为名为“每日工单异常审查”的技能。</span></span>
<span class="line"><span>技能内容必须包含以下要素：</span></span>
<span class="line"><span>1. 适用场景：工作日审查支持渠道中滞留超过 4 小时的工单。</span></span>
<span class="line"><span>2. 输入数据：从已连接的工单插件中读取状态为 Open 且优先级为 High 的列表。</span></span>
<span class="line"><span>3. 决策规则：若工单包含退款申请且金额大于 500 元，标记为一级风险；其余标记为二级跟进。</span></span>
<span class="line"><span>4. 交付格式：生成 Markdown 表格，列出工单编号、客户标识、滞留时长、风险等级与跟进建议。</span></span>
<span class="line"><span>5. 异常处理：若工单系统接口无响应或无符合条件的数据，输出明确说明，严禁使用历史缓存或伪造数据。</span></span>
<span class="line"><span>6. 安全边界：未经人工明确批准，严禁直接调用接口回复客户或变更工单状态。</span></span></code></pre></div></details><p><strong>方式二：演示教会（Teach task）</strong> 界面操作复杂时，直接演示更省事。</p><ol><li>聊天窗口右侧打开计算机预览，选择“教会任务”（Teach task）。</li><li>简述目标后在云电脑上操作。<strong>系统最多录 10 分钟屏幕且不录麦克风音频，切勿输入密码等机密，敏感凭据走安全卡片</strong>。</li><li>自动生成草稿后，<strong>必须补齐决策规则、报错与审批边界，切勿直接上线</strong>。没看到入口说明还在灰度，改用方式一。</li></ol><h3 id="如何引用与管理技能" tabindex="-1">如何引用与管理技能 <a class="header-anchor" href="#如何引用与管理技能" aria-label="Permalink to &quot;如何引用与管理技能&quot;">​</a></h3><ul><li><strong>输入框引用</strong>：输入框输入斜杠 <code>/</code> 即可选择技能载入。</li><li><strong>开启权限</strong>：列表中找不到时，去桌面侧边栏“连接应用”（Connected Apps）点已连数量，在“私有技能”里打开开关。</li></ul><h3 id="做到什么程度算合格" tabindex="-1">做到什么程度算合格 <a class="header-anchor" href="#做到什么程度算合格" aria-label="Permalink to &quot;做到什么程度算合格&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">检查项</th><th style="text-align:left;">不合格写法</th><th style="text-align:left;">合格写法</th></tr></thead><tbody><tr><td style="text-align:left;">输入来源</td><td style="text-align:left;">“分析一下最近的数据”</td><td style="text-align:left;">明确指定插件、API 端点、文件路径或数据库视图</td></tr><tr><td style="text-align:left;">边界控制</td><td style="text-align:left;">“遇到问题看着办”</td><td style="text-align:left;">数据缺失立即中断报错，严禁编造数据</td></tr><tr><td style="text-align:left;">动作权限</td><td style="text-align:left;">“帮我把报表发给客户”</td><td style="text-align:left;">生成草稿并在聊天停留，<strong>等人工允许后再发送</strong></td></tr><tr><td style="text-align:left;">输出结构</td><td style="text-align:left;">自由发挥的大段文本</td><td style="text-align:left;">固定字段列表、Markdown 表格或落盘路径</td></tr></tbody></table><p>出处：<a href="https://cursor.com/cn/docs/grok-bot/work.md" target="_blank" rel="noreferrer">《使用 Grok Bot》</a></p><h2 id="例程的核心机制-设置、查看与测试" tabindex="-1">例程的核心机制：设置、查看与测试 <a class="header-anchor" href="#例程的核心机制-设置、查看与测试" aria-label="Permalink to &quot;例程的核心机制：设置、查看与测试&quot;">​</a></h2><p><img src="`+s+'" alt="例程的核心机制：设置、查看与测试" width="1600" height="1013" loading="lazy" decoding="async"></p><p>例程是挂在 Bot 名下的工作流触发器，跑在云端 Linux 的 <code>/workspace</code> 目录。<strong>就算合上电脑或退出客户端，云端任务也会按计划推进。</strong></p><h3 id="规格与限制" tabindex="-1">规格与限制 <a class="header-anchor" href="#规格与限制" aria-label="Permalink to &quot;规格与限制&quot;">​</a></h3><ul><li>每个 Bot 最多创建 50 个例程，系统保留最近 20 次运行记录。</li><li>定时例程最短触发间隔为 5 分钟，不支持秒级调度。</li><li><strong>删除例程不可逆</strong>，后续执行会永久终止；删除 Bot 会连带清空全部例程。</li></ul><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/HHmpwgN4qi86e0kgBvAc1156nkg" target="_blank" rel="noreferrer">《4.3 触发器与自动化：定时、Webhook、在 X 上派活》</a>。</p><h3 id="创建与管理例程" tabindex="-1">创建与管理例程 <a class="header-anchor" href="#创建与管理例程" aria-label="Permalink to &quot;创建与管理例程&quot;">​</a></h3><p>桌面端在聊天框发指令直接创建：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个工作日上午 8:30，调用“每日工单异常审查”技能，在此对话中输出审查清单。如果未检索到高风险工单，只发一行“今日无高风险工单”即可，不要刷屏。</span></span></code></pre></div><p>桌面端管理：</p><ol><li>点击聊天窗口顶部的 Bot 名称进入 Details，在例程（Routines）列表能看运行时间或 Paused，右侧开关随时暂停（Pause）或恢复（Resume）。</li><li>点击具体例程可查三项属性：Instruction（执行提示词）、When to run（计划描述）与 Webhook（专属 URL、密钥与请求头）。</li><li>底部工具栏提供 Test、Edit 与红色垃圾桶（Delete routine）。<strong>点击 Edit 会在对话框预填 &quot;Edit your routine: [例程名]&quot;</strong>，补上修改要求发送即可更新。</li></ol><p>手机端管理：</p><ol><li>打开 Bot 资料页找到例程，点击 Add routine 会预填 &quot;Set up a routine to &quot;，补齐指令发送即可创建。</li><li>点击已有例程能查 Schedule、Next run 与 Instruction，也能看 Active 开关和运行历史（Run history）。</li><li><strong>关闭 Active 开关即可暂停，向左滑动所在行可直接删除。</strong> 状态与桌面端双向实时同步。</li></ol><p>出处：<a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">《例程》</a>。</p><h3 id="计划调度与时区配置" tabindex="-1">计划调度与时区配置 <a class="header-anchor" href="#计划调度与时区配置" aria-label="Permalink to &quot;计划调度与时区配置&quot;">​</a></h3><p>时区检查路径：Settings -&gt; Bot -&gt; Timezone。</p><table tabindex="0"><thead><tr><th style="text-align:left;">模式</th><th style="text-align:left;">运行机制</th><th style="text-align:left;">注意事项</th></tr></thead><tbody><tr><td style="text-align:left;">Auto-detect</td><td style="text-align:left;">自动跟随当前电脑时区</td><td style="text-align:left;">适合固定地点；跨国差旅容易导致运行时间变动</td></tr><tr><td style="text-align:left;">手动指定时区</td><td style="text-align:left;">手动下拉选择对应时区</td><td style="text-align:left;">面向特定区域（如北京时间 UTC+8 或美东 EST）建议手动指定</td></tr></tbody></table><ul><li><strong>新建定时例程不会立刻首跑</strong>，必须等待下一个计划时间点。例如早上 8:05 设每天 8:00 运行，首次执行是在明早 8:00。</li><li><strong>周末若需连续巡检，指令中必须明确强调“包括周末在内每天运行”。</strong> 未作特殊声明时，Bot 默认按周一至周五执行。</li></ul><p>出处：<a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">《例程》</a>，<a href="https://jcng5q8n0f3z.feishu.cn/wiki/HHmpwgN4qi86e0kgBvAc1156nkg" target="_blank" rel="noreferrer">《4.3 触发器与自动化：定时、Webhook、在 X 上派活》</a>。</p><h3 id="测试例程" tabindex="-1">测试例程 <a class="header-anchor" href="#测试例程" aria-label="Permalink to &quot;测试例程&quot;">​</a></h3><p>在桌面端详情页点击底部的 Test 按钮即可手动触发，按钮状态会变为 Running…，执行反馈直接打在聊天窗口中。</p><p><strong>测试执行的是真实操作</strong>，会启动云电脑浏览器、改写工作区文件并正常扣除额度，涉及删改先用沙箱数据测试。<strong>若提示 Couldn&#39;t start a test run，需要检查云电脑连接状态或是否有前序任务阻塞。</strong></p><p>出处：<a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">《例程》</a>。</p><h2 id="webhook-与-slack-触发器-从轮询走向被动唤醒" tabindex="-1">Webhook 与 Slack 触发器：从轮询走向被动唤醒 <a class="header-anchor" href="#webhook-与-slack-触发器-从轮询走向被动唤醒" aria-label="Permalink to &quot;Webhook 与 Slack 触发器：从轮询走向被动唤醒&quot;">​</a></h2><p><img src="'+i+`" alt="Webhook 与 Slack 触发器：从轮询走向被动唤醒" width="1600" height="1013" loading="lazy" decoding="async"></p><p>定时轮询外部网页极费额度，高频空转会迅速耗尽整周算力。<strong>改用事件驱动唤醒 Bot</strong>，平时彻底休眠，外部有变化时再被动触发。</p><p>2026-10-12 起，Grok Bot 纳入 The X Subscription 体系，与 Grok、Cursor 共享额度池：</p><table tabindex="0"><thead><tr><th style="text-align:left;">订阅档位</th><th style="text-align:left;">价格</th><th style="text-align:left;">用量倍数</th><th style="text-align:left;">Bot 支持情况</th></tr></thead><tbody><tr><td style="text-align:left;">Premium</td><td style="text-align:left;">每月 $30 或每年 $300</td><td style="text-align:left;">4 倍基础用量</td><td style="text-align:left;">包含 Bot</td></tr><tr><td style="text-align:left;">Super</td><td style="text-align:left;">每月 $100 或每年 $1000</td><td style="text-align:left;">15 倍用量</td><td style="text-align:left;">包含 Bot</td></tr><tr><td style="text-align:left;">Ultra</td><td style="text-align:left;">每月 $200 或每年 $2000</td><td style="text-align:left;">50 倍用量</td><td style="text-align:left;">包含 Bot</td></tr><tr><td style="text-align:left;">Plus</td><td style="text-align:left;">-</td><td style="text-align:left;">-</td><td style="text-align:left;">不包含 Bot</td></tr></tbody></table><h3 id="webhook-配置与异步验收" tabindex="-1">Webhook 配置与异步验收 <a class="header-anchor" href="#webhook-配置与异步验收" aria-label="Permalink to &quot;Webhook 配置与异步验收&quot;">​</a></h3><p>在聊天窗口发送指令，可让 Bot 创建 Webhook 触发器。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为当前 Bot 创建一个 Webhook 触发的例程，命名为“外部知识接收端”。</span></span>
<span class="line"><span>指令内容：读取请求体中的 JSON 数据，提取 url 和 note 字段，将其抓取整理为 Markdown 存入 /workspace/notes 目录。</span></span></code></pre></div><p>在桌面端打开例程详情，展开 Webhook 查看核心字段：</p><ol><li>POST to：接收外部请求的公网唯一 URL。</li><li>key：鉴权私钥，调用时需在请求头携带 <code>Authorization: Bearer &lt;key&gt;</code>。</li><li>header：拼接完整的请求头文本，点击可直接复制。</li></ol><p><strong>配置必须点击 Save 保存后才会在网关生效并生成密钥。</strong> 详情页若卡住点不开，让 Bot 发送直达链接。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/HHmpwgN4qi86e0kgBvAc1156nkg" target="_blank" rel="noreferrer">《4.3 触发器与自动化：定时、Webhook、在 X 上派活》</a></p><p>外部系统通过 POST 请求推送数据，直接带上 JSON 请求体。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/article/1024&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ios_share&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;note&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;精读核心论点并归档&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Bot 会把 JSON 作为上下文变量，连同预设 Instruction 一同送入模型。<a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">《例程》</a></p><ul><li><strong>HTTP 200 仅代表网关成功接收请求并启动运行，不代表任务执行成功。</strong> 业务成败需在聊天窗口或工作区落盘文件查看。</li><li>返回非 200 说明任务未建立，通常因例程处于暂停（Paused）状态或密钥失效。<a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">《例程》</a></li></ul><h3 id="slack-触发器与防爆额度" tabindex="-1">Slack 触发器与防爆额度 <a class="header-anchor" href="#slack-触发器与防爆额度" aria-label="Permalink to &quot;Slack 触发器与防爆额度&quot;">​</a></h3><p>Slack 插件是随对话实时调用的读写工具；Slack 触发器是例程启动条件，使用前必须在 Cursor 账号集成中完成授权。</p><p>用自然语言发指令，即可建立监听。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建一个 Slack 触发例程：当 #incident-response 频道中有人发消息提及 @bot 且包含短语 &quot;needs repro&quot; 时，在云电脑上拉取报错日志并尝试复现。不要监听其他频道，也不要在没有该短语时响应。</span></span></code></pre></div><p>监听类型支持四种：Bot 被提及、匹配特定词句、添加表情回应，或是接收任意消息。</p><ul><li><strong>严禁在公共频道监听任意消息</strong>，闲聊打卡会触发全量匹配，整周额度一天就会烧光。</li><li>必须绑定单一专属频道，不能选“整个工作区”。</li><li>过滤条件尽量收紧，比如限定特定前缀或工单链接。</li><li>触发器只对创建后的新消息生效，历史消息不追溯。<a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">《例程》</a></li></ul><h2 id="自动化实战案例-三种典型流水线" tabindex="-1">自动化实战案例：三种典型流水线 <a class="header-anchor" href="#自动化实战案例-三种典型流水线" aria-label="Permalink to &quot;自动化实战案例：三种典型流水线&quot;">​</a></h2><h3 id="案例-1-手机一键入库知识库-ios-快捷指令-webhook" tabindex="-1">案例 1：手机一键入库知识库（iOS 快捷指令 + Webhook） <a class="header-anchor" href="#案例-1-手机一键入库知识库-ios-快捷指令-webhook" aria-label="Permalink to &quot;案例 1：手机一键入库知识库（iOS 快捷指令 + Webhook）&quot;">​</a></h3><p>社区作者铁柱（@cgnot996）搭了一套归档流。在手机上刷到技术文章或视频时点系统分享，Grok Bot 会自动抓全文、提要点，整理成 Markdown 格式写进 <code>/workspace/knowledge/inbox.md</code>。</p><p>按这几步配置。</p><ol><li><strong>新建云端例程</strong>：在 Grok Bot 端新建“手机知识归档”例程，触发条件选 Webhook，拿到专属的 POST URL 和 Authorization 标头。</li><li><strong>编写处理指令</strong>：指令设为接收传入的 URL，在云电脑用浏览器打开；要是视频就提取文稿；解析完后按格式提取标题与标签，并整理核心要点与关联链接，追加写入 <code>/workspace/knowledge/inbox.md</code>。</li><li><strong>创建手机快捷指令</strong>：在 iPhone 打开“快捷指令”App 新建一条，打开“在共享表单中显示”，接收类型勾选“网页和文本”。</li><li><strong>添加请求节点</strong>：添加“获取 URL 内容”节点，方法选 <code>POST</code>，URL 填 Webhook 目标地址，头部加 <code>Authorization</code> 值为 <code>Bearer [你的私钥]</code>，请求体选 <code>JSON</code> 并将 <code>url</code> 绑定到“快捷指令输入”。</li><li><strong>解决分享限制</strong>：微信公众号等应用无法直接唤起带快捷指令的分享面板。<strong>额外建一条“输入框中转”快捷指令绑到操作按钮（Action Button）</strong>，点开弹窗贴链接，再转发给 Webhook。</li></ol><p><strong>手机端只做轻量参数捕获与 HTTP 发送，繁重的内容抓取和排版全交给云端异步跑。</strong> 这样手机不耗电也不用等，几秒就能退出来。</p><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/Kxtxw9gLBiqi0nkhZpCc7le5nrh" target="_blank" rel="noreferrer">《Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建》</a>，<a href="https://jcng5q8n0f3z.feishu.cn/wiki/HHmpwgN4qi86e0kgBvAc1156nkg" target="_blank" rel="noreferrer">《4.3 触发器与自动化：定时、Webhook、在 X 上派活》</a>。</p><h3 id="案例-2-虚拟机两段式巡检与额度极限优化" tabindex="-1">案例 2：虚拟机两段式巡检与额度极限优化 <a class="header-anchor" href="#案例-2-虚拟机两段式巡检与额度极限优化" aria-label="Permalink to &quot;案例 2：虚拟机两段式巡检与额度极限优化&quot;">​</a></h3><p>社区作者铁柱（@cgnot996）优化了“营销总监”Bot 的 6 条例行任务。他把盯 xAI 回复和每日审 PR 这两项纯等变动的巡检改成轻量比对，有实质进展才叫醒模型，每周省下 8 至 10 次无效空转。</p><p>任务分为两类。</p><table tabindex="0"><thead><tr><th style="text-align:left;">任务类型</th><th style="text-align:left;">典型代表</th><th style="text-align:left;">调度策略与运行特征</th></tr></thead><tbody><tr><td style="text-align:left;">到点必须交付产物</td><td style="text-align:left;">SEO 日报、权重月报</td><td style="text-align:left;">到点产出完整报告让人查阅，保留原生定时调度</td></tr><tr><td style="text-align:left;">到点单纯等待变动</td><td style="text-align:left;">监控页面更新、新 PR 检查</td><td style="text-align:left;">定时空转会扣额度，需要改成轻量检测</td></tr></tbody></table><p>落地分四步走。</p><ol><li><strong>部署本地哨兵</strong>：在 Grok Bot 跑着的 Linux 虚拟机本地写一个极简脚本，用 Python 或 Bash 都行，完全不调大模型。</li><li><strong>配置定时比对</strong>：用 Linux 自带的 <code>cron</code> 定时器跑脚本，工作日每半小时查一次。脚本只比对网页哈希值或查 GitHub 接口看 PR 数，耗时几秒且不消耗 Grok 订阅额度。</li><li><strong>实施差异唤醒</strong>：<strong>比对发现实质变动后，脚本才执行 <code>curl</code> 向 Webhook 发起 POST 调用。</strong></li><li><strong>模型介入处置</strong>：Bot 醒来后开始读 PR 代码或回复内容，梳理决策建议并推送通知。</li></ol><p>机械判断交给本地脚本，需要动脑才叫醒大模型。这样不用为了一句“今日无事发生”白白消耗大模型上下文。</p><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/SDr3wRrG5iGmz1kejdTcss0Rned" target="_blank" rel="noreferrer">《Grok Bot 额度再省一点：定时任务极限优化》</a>。</p><h3 id="案例-3-每日客户流失风险监测" tabindex="-1">案例 3：每日客户流失风险监测 <a class="header-anchor" href="#案例-3-每日客户流失风险监测" aria-label="Permalink to &quot;案例 3：每日客户流失风险监测&quot;">​</a></h3><p>官方团队与运营 29 个 Bot 的作者 melvindvivas 采用这套方案监控客户异动。每天早晨自动拉取用量与工单指标，生成预警观察清单，全程严格受控。</p><p>落地分四步走。</p><ol><li><strong>确立岗位章程合同</strong>：建专职 Account Risk Bot，在 Profile 的 Description 写明规则合同，定好风险阈值。比如 API 调用量连续三天跌幅超 40%，且伴随没解决的 P1 工单。</li><li><strong>设定定时拉取任务</strong>：配好工作日早晨 8:00 跑的例程，定时拉取源系统指标。</li><li><strong>配置故障熔断机制</strong>：<strong>数据仓库连接超时或数据未就绪，直接报告缺失失败原因，严禁拿昨天快照推测，严禁输出未证实数据。</strong></li><li><strong>设置安全审批人闸</strong>：在 Settings 的 Custom Rules 里把发邮件、修改 CRM 字段和分发清单全部设为“先询问”（Ask first）。Bot 整理出的清单只在聊天窗口静默展示，等客户经理核实后手动点击批准卡片。</li></ol><p><strong>高价值自动化不能只给模型放权，赋予执行能力的同时必须加上边界合同与人工闸门。</strong></p><p>出处：<a href="https://cursor.com/cn/docs/grok-bot/work.md" target="_blank" rel="noreferrer">《使用 Grok Bot》</a>，<a href="https://jcng5q8n0f3z.feishu.cn/wiki/HHmpwgN4qi86e0kgBvAc1156nkg" target="_blank" rel="noreferrer">《4.3 触发器与自动化：定时、Webhook、在 X 上派活》</a>。</p><h2 id="例程排错指南" tabindex="-1">例程排错指南 <a class="header-anchor" href="#例程排错指南" aria-label="Permalink to &quot;例程排错指南&quot;">​</a></h2><h3 id="计划时间到了-bot-完全没有反应" tabindex="-1">计划时间到了，Bot 完全没有反应 <a class="header-anchor" href="#计划时间到了-bot-完全没有反应" aria-label="Permalink to &quot;计划时间到了，Bot 完全没有反应&quot;">​</a></h3><ul><li>桌面端 Details 确认未被 Paused，手机端确认 Active 开启。<strong>久未登录超时未回 Bot 确认，任务会自动暂停</strong>。</li><li>核对 When to run 时区与周末设置。新建计划只等下个自然周期，先点 Test 测链路。</li><li>手机端查“运行历史”，<strong>显示 No runs yet 说明信号没进网关</strong>，显示 Failed 可点开看具体报错。</li></ul><p>出处：<a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">《例程》</a></p><h3 id="外部-webhook-推送了-但例程未启动" tabindex="-1">外部 Webhook 推送了，但例程未启动 <a class="header-anchor" href="#外部-webhook-推送了-但例程未启动" aria-label="Permalink to &quot;外部 Webhook 推送了，但例程未启动&quot;">​</a></h3><ul><li>调接口先看返回值，<strong>非 200 说明请求被网关拦截</strong>。</li><li>核对请求头 <code>Authorization</code> 的 Bearer 密钥，重新生成后旧密钥立刻作废。</li><li>新建触发器后<strong>必须点右下角 Save</strong>，端点和密钥才会在网关生效。</li></ul><p>出处：<a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">《例程》</a></p><h3 id="slack-触发器不触发" tabindex="-1">Slack 触发器不触发 <a class="header-anchor" href="#slack-触发器不触发" aria-label="Permalink to &quot;Slack 触发器不触发&quot;">​</a></h3><ul><li>触发器<strong>只对上线后的新增消息生效</strong>，编辑历史消息不会触发。</li><li>确认没发错频道，账号在目标频道需有读取权限，<strong>关键词要精确匹配</strong>。</li></ul><p>出处：<a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">《例程》</a></p><h3 id="任务跑了一半突然卡死中断" tabindex="-1">任务跑了一半突然卡死中断 <a class="header-anchor" href="#任务跑了一半突然卡死中断" aria-label="Permalink to &quot;任务跑了一半突然卡死中断&quot;">​</a></h3><ul><li>后台无人值守的审批卡片<strong>只等待约 10 分钟</strong>，超时变 Expired 就会中断失败。</li><li>开启通知，或在 Settings &gt; Bot &gt; Auto-review 模式的“自定义规则”中放行信任动作自动执行。</li><li>遇报错右键气泡点 <strong>Copy request ID</strong>，带上报错文本找官方调日志排查。</li></ul><p>出处：<a href="https://cursor.com/cn/help/grok-bot/how-to.md" target="_blank" rel="noreferrer">《Grok Bot 操作指南》</a></p><h3 id="云电脑更新后-本地脚本与定时器丢失" tabindex="-1">云电脑更新后，本地脚本与定时器丢失 <a class="header-anchor" href="#云电脑更新后-本地脚本与定时器丢失" aria-label="Permalink to &quot;云电脑更新后，本地脚本与定时器丢失&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">更新类型</th><th style="text-align:left;">环境保留情况</th></tr></thead><tbody><tr><td style="text-align:left;">软件更新</td><td style="text-align:left;">云电脑环境与文件不受影响</td></tr><tr><td style="text-align:left;">计算机更新（“设置”&gt;“计算机”&gt;“更新 Bot 的计算机”）</td><td style="text-align:left;">重构镜像；保留 <code>/workspace</code> 与浏览器登录态，<strong>清空 apt 全局包（如 cron）</strong></td></tr></tbody></table><p>出处：<a href="https://cursor.com/cn/help/grok-bot/how-to.md" target="_blank" rel="noreferrer">《Grok Bot 操作指南》</a>，<a href="https://jcng5q8n0f3z.feishu.cn/wiki/SDr3wRrG5iGmz1kejdTcss0Rned" target="_blank" rel="noreferrer">《Grok Bot 额度再省一点：定时任务极限优化》</a></p><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><ol><li><p><strong>点 Test 会真执行</strong>：会调用工具删文件，<strong>测试前在指令留审批断点</strong>。<a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">《例程》</a>。</p></li><li><p><strong>轮询与定时机制</strong>：每 5 分钟轮询耗尽整周额度，<strong>用轻量脚本比对，有变动再唤醒模型</strong>。“每天 9 点”默认工作日跑，<strong>注明“包括周末在内”，在 Settings 固定时区</strong>。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/HHmpwgN4qi86e0kgBvAc1156nkg" target="_blank" rel="noreferrer">《4.3 触发器与自动化：定时、Webhook、在 X 上派活》</a>。</p></li><li><p><strong>聊天框勿贴 Webhook 密钥</strong>：会记入云端历史。<strong>凭证须在安全机密信息请求卡片输入</strong>，误贴立刻删除。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/SDr3wRrG5iGmz1kejdTcss0Rned" target="_blank" rel="noreferrer">《Grok Bot 额度再省一点：定时任务极限优化》</a>。</p></li><li><p><strong>防审批拦截静默失败</strong>：设拦截须开移动端通知。<strong>审批弹出后 10 分钟无人应答超时报废</strong>。<a href="https://cursor.com/cn/help/grok-bot/how-to.md" target="_blank" rel="noreferrer">《Grok Bot 操作指南》</a>。</p></li><li><p><strong>Bot 共享环境</strong>：在 <code>/workspace/temp</code> 删文件影响其他 Bot，<strong>写文件须为各项目指定独立子目录</strong>。</p><p><a href="https://cursor.com/cn/docs/grok-bot/work.md" target="_blank" rel="noreferrer">《使用 Grok Bot》</a>。</p></li></ol><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><p>按顺序过完这四步，<strong>全通过才能放手让它无人值守</strong>：</p><ol><li>核对时间：在详情页确认 <strong>Next run</strong> 时间戳和本地时区完全对得上。</li><li>测缺数据：断网或传空文件点 Test，例程必须报错终止，不能瞎编内容。</li><li>测审批拦截：故意发删除或外发指令，要是没弹卡直接执行，说明有漏洞，得去 Settings 补。</li><li>查日志落盘：正常跑一次，去 <code>/workspace</code> 确认文档已写入，且聊天窗口没有刷屏。</li></ol><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/HHmpwgN4qi86e0kgBvAc1156nkg" target="_blank" rel="noreferrer">《4.3 触发器与自动化：定时、Webhook、在 X 上派活》</a>。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><h3 id="相关章节" tabindex="-1">相关章节 <a class="header-anchor" href="#相关章节" aria-label="Permalink to &quot;相关章节&quot;">​</a></h3><ul><li><a href="/part3/20-automation">第 20 章 可靠的自动化：定时、Webhook 与事件触发</a></li></ul><h3 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h3><ul><li><a href="https://cursor.com/cn/docs/grok-bot/work.md" target="_blank" rel="noreferrer">《使用 Grok Bot》</a></li><li><a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">《例程》</a></li><li><a href="https://cursor.com/cn/help/grok-bot/how-to.md" target="_blank" rel="noreferrer">《Grok Bot 操作指南》</a></li></ul><h3 id="社区实战" tabindex="-1">社区实战 <a class="header-anchor" href="#社区实战" aria-label="Permalink to &quot;社区实战&quot;">​</a></h3><ul><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/HHmpwgN4qi86e0kgBvAc1156nkg" target="_blank" rel="noreferrer">《4.3 触发器与自动化：定时、Webhook、在 X 上派活》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/SDr3wRrG5iGmz1kejdTcss0Rned" target="_blank" rel="noreferrer">《Grok Bot 额度再省一点：定时任务极限优化》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/Kxtxw9gLBiqi0nkhZpCc7le5nrh" target="_blank" rel="noreferrer">《Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建》</a></li></ul>`,114)])])}const m=e(h,[["render",d]]);export{f as __pageData,m as default};
